1#include <iostream>
2using namespace std;
3
4class Circle {   
5    public:
6
7        double pi = 3.14;
8        double radius;
9  
10        // constructor to initialize radius
11        Circle(double rad): radius(rad) {}
12  
13        // function to calculate area
14        double calculate_area() {
15            return pi * radius * radius;
16        }
17};
18
19int main() {
20
21    // create object of Circle
22    // pass a double value as argument
23    Circle circle(6.99);
24  
25    // call calculate_area() function
